<script setup lang="ts">
// DictionarySelect (generated by engineering-platform frontend-enterprise-management asset)
// Reusable dictionary-driven select. Input: dictionary code (e.g. product_status).
// Loads items, filters enabled, maps value/label. Business pages never repeat
// dictionary API calls.
import { onMounted, ref, watch } from 'vue';
import { dictionaryApi } from '../api/enterprise';
import type { DictionaryItem } from '../types/enterprise';

const props = withDefaults(
  defineProps<{
    code: string;
    modelValue?: string | number | null;
    placeholder?: string;
    /** When true, also show disabled items (management surfaces). */
    includeDisabled?: boolean;
    clearable?: boolean;
    disabled?: boolean;
  }>(),
  {
    modelValue: null,
    placeholder: 'Select',
    includeDisabled: false,
    clearable: false,
    disabled: false,
  },
);

const emit = defineEmits<{
  'update:modelValue': [value: string | number | null];
}>();

const items = ref<DictionaryItem[]>([]);
const loading = ref(false);
const error = ref<string | null>(null);

async function load(): Promise<void> {
  loading.value = true;
  error.value = null;
  try {
    const data = await dictionaryApi.itemsByCode(props.code);
    items.value = data;
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Failed to load dictionary';
  } finally {
    loading.value = false;
  }
}

function onSelect(value: string | number | null): void {
  emit('update:modelValue', value);
}

watch(() => props.code, load, { immediate: false });
onMounted(load);

defineExpose({ load, items });
</script>

<template>
  <div class="dictionary-select" data-testid="dictionary-select">
    <el-select
      :model-value="modelValue ?? undefined"
      :placeholder="placeholder"
      :loading="loading"
      :clearable="clearable"
      :disabled="disabled"
      :class="{ 'is-error': error }"
      data-testid="dictionary-select-control"
      @update:model-value="onSelect"
    >
      <el-option
        v-for="item in items"
        :key="item.id"
        :value="item.value"
        :label="item.label"
        :disabled="!item.enabled && !includeDisabled"
      />
    </el-select>
    <span v-if="error" class="dictionary-select-error">{{ error }}</span>
  </div>
</template>

<style scoped>
.dictionary-select-error {
  display: block;
  color: var(--el-color-danger);
  font-size: var(--ep-font-size-sm);
  margin-top: var(--ep-space-1);
}
</style>
